/// A traced picture drawn at the size it has in the reference, in the colour it is given.
struct NunaTracedIconView: View {
    let icon: NunaTracedIcon
    var body: some View {
        NunaTracedIconShape(icon: icon).fill(style: FillStyle(eoFill: true)).frame(width: icon.width, height: icon.height).accessibilityHidden(true)
    }
}

private struct NunaTracedIconShape: Shape {
    let icon: NunaTracedIcon
    func path(in rect: CGRect) -> Path {
        let side = max(rect.width, rect.height)
        var p = Path()
        for c in icon.contours {
            guard let first = c.first else { continue }
            p.move(to: CGPoint(x: rect.minX + first.x * side, y: rect.minY + first.y * side))
            for pt in c.dropFirst() { p.addLine(to: CGPoint(x: rect.minX + pt.x * side, y: rect.minY + pt.y * side)) }
            p.closeSubpath()
        }
        return p
    }
}
